{
  "headline": "FDA's records trace our supply to a plant classified OAI 364 days before the shortage posting",
  "headline_cites": ["D4"],
  "sentences": [
    {
      "text": "FDA posted the chloroprocaine hydrochloride shortage on 2021-05-17 and it has remained on the list for 65 months as of 2026-10-21.",
      "cites": ["D11"]
    },
    {
      "text": "An FDA inspection of Fresenius Kabi USA, LLC (FEI 1450022) ended on 2020-05-18 and was classified OAI, with the classification letter issued 364 days before the shortage posting.",
      "cites": ["D4", "E12"]
    },
    {
      "text": "A second inspection of the same plant ended on 2022-06-30 and was also classified OAI, with the classification letter issued 409 days after the shortage posting.",
      "cites": ["D5", "E13"]
    },
    {
      "text": "Corvale General's inventory includes product from Fresenius Kabi USA, LLC (NDC 63323047537) and from Hikma Pharmaceuticals USA Inc. (NDC 00143920910).",
      "cites": ["E2", "E3", "E6", "E15"]
    },
    {
      "text": "The P&T committee has approved interchangeability between the Fresenius Kabi and Hikma presentations of chloroprocaine hydrochloride.",
      "cites": ["E16"]
    },
    {
      "text": "Corvale General holds 15 days on hand and can spare 7 units while keeping two weeks of supply; Corvale East has 8.1 days on hand and would reach 10 days after the transfer.",
      "cites": ["D2", "D1", "D8"]
    }
  ]
}
